<?php
namespace App\Http\Controllers;use App\Models\KycProfile;use App\Services\AuditService;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class KycController extends Controller{public function show(Request $r){return view('kyc.show',['profile'=>KycProfile::where('user_id',$r->user()->id)->first()]);}public function store(Request $r,AuditService $audit){$data=$r->validate(['legal_name'=>'required|string|max:120','date_of_birth'=>'required|date|before:-18 years','country_code'=>'required|string|size:2','document_type'=>'required|in:passport,national_id,drivers_license','document'=>'required|file|mimes:pdf,jpg,jpeg,png|max:10240']);$file=$r->file('document');$sha=hash_file('sha256',$file->getRealPath());try{$path=$file->store("kyc/{$r->user()->id}",'local');if(!$path)throw new \RuntimeException('Private document storage returned no path.');}catch(\Throwable $e){report($e);return back()->withInput()->withErrors(['document'=>'We could not securely store this document. Please retry with a PDF, JPG, or PNG under 10 MB.']);}$old=KycProfile::where('user_id',$r->user()->id)->first();$profile=KycProfile::updateOrCreate(['user_id'=>$r->user()->id],['legal_name'=>$data['legal_name'],'date_of_birth'=>$data['date_of_birth'],'country_code'=>strtoupper($data['country_code']),'document_type'=>$data['document_type'],'document_path'=>$path,'document_sha256'=>$sha]);if($old&&$old->document_path!==$path)Storage::disk('local')->delete($old->document_path);$r->user()->update(['kyc_status'=>'pending','sanctions_status'=>'pending']);$audit->record('kyc.submitted',$profile,[],['document_sha256'=>$profile->document_sha256],$r);return back()->with('status','KYC submitted for platform compliance review.');}}
